const trig = $('Telegram Trigger').first().json;
const msg = trig.message ?? {};
const chatId = String(msg.chat?.id ?? '');
const userId = msg.from?.id ?? null;
const raw = String(msg.text ?? msg.caption ?? '').trim();

const norm = s => String(s ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .toLowerCase().replace(/\s+/g,' ').trim();
const t = norm(raw);

function ms(v){ const d=new Date(v); return isNaN(d)?0:d.getTime(); }
function persona(){
  if(Number(userId)===111111111) return 'Titular A';
  if(Number(userId)===222222222) return 'Titular B';
  return 'Sin identificar';
}
function expiry(hours=2){
  return new Date(Date.now()+hours*60*60*1000).toISOString();
}
function pendingRow(data, field, question, status='PENDIENTE', intent='UI_MOVIMIENTO'){
  return {
    "ID pendiente": `UI-MOV-${chatId}`,
    "Chat ID": msg.chat?.id ?? null,
    "Telegram User ID": userId,
    "Persona": persona(),
    "Fecha/Hora": new Date().toISOString(),
    "Intención": intent,
    "Mensaje original": raw,
    "Datos parciales JSON": JSON.stringify(data ?? {}),
    "Campo pendiente": field ?? null,
    "Pregunta enviada": question ?? null,
    "Opciones sugeridas": null,
    "Confianza": 1,
    "Estado": status,
    "Expira": status==='PENDIENTE' ? expiry(2) : new Date().toISOString(),
    "Mensaje Telegram ID": msg.message_id ?? null
  };
}

const allPending = items.map(i=>i.json);
const candidates = allPending.filter(r =>
  String(r['Chat ID']??'')===chatId &&
  String(r['Intención']||'').toUpperCase()==='UI_MOVIMIENTO' &&
  String(r.Estado||'').toUpperCase()==='PENDIENTE' &&
  (!r.Expira || ms(r.Expira)>Date.now())
).sort((a,b)=>ms(b['Fecha/Hora'])-ms(a['Fecha/Hora']));

const activeRow = candidates[0] || null;
const activeIntent='UI_MOVIMIENTO';
let st = null;
if(activeRow){
  try{ st=JSON.parse(activeRow['Datos parciales JSON']||'null'); }catch(e){}
}

function parseMoney(raw) {
  if (!raw) return null;
  let s = String(raw).replace(/[^\d.,-]/g,'').trim();
  if (!s) return null;
  const hasComma=s.includes(','), hasDot=s.includes('.');
  if (hasComma && hasDot) s=s.replace(/\./g,'').replace(',','.');
  else if (hasComma) s=s.replace(',','.');
  else if (hasDot && /^\d{1,3}(\.\d{3})+$/.test(s)) s=s.replace(/\./g,'');
  const n=Number(s);
  return Number.isFinite(n)?n:null;
}
function parseAmountDetail(input){
  const s=String(input||'').trim();
  const m=s.match(/^\s*\$?\s*(-?\d[\d.]*(?:,\d{1,2})?)\s*(.*)$/);
  if(!m) return null;
  const amount=parseMoney(m[1]);
  if(amount===null) return null;
  let rest=String(m[2]||'').trim();
  const usdRx=/(?:\bUSD\b|U\$S|US\$|\bDLS\b|\bD[ÓO]LARES?\b)/i;
  const currency=usdRx.test(rest)?'USD':'ARS';
  let cot=null;
  if(currency==='USD'){
    const cm=rest.match(/\b(?:cot|cotiz(?:acion|ación)?)\.?\s*[:=]?\s*\$?\s*(\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?|\d+(?:[.,]\d{1,2})?)/i);
    if(cm){ cot=parseMoney(cm[1]); rest=rest.replace(cm[0],' ').trim(); }
    rest=rest.replace(usdRx,' ').replace(/\s+/g,' ').trim();
  }
  return {amount,detail:rest||null,currency,cot:(cot&&cot>0)?cot:null};
}
function todayIso(){
  const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Argentina/Buenos_Aires',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
  const g=x=>parts.find(p=>p.type===x)?.value;
  return `${g('year')}-${g('month')}-${g('day')}`;
}

const CANCEL = ['cancelar','❌ cancelar','↩️ menu principal','↩️ menú principal','🏠 menu principal','🏠 menú principal'];
if(st && CANCEL.includes(t)){
  return [{json:{
    ...trig,
    ui_mode:'main',ui_only:true,chat_id:msg.chat?.id,
    ui_pending_write:true,
    ui_pending_row:pendingRow(st,'cancelado','Flujo cancelado','CANCELADO',activeIntent)
  }}];
}
// --------------------------------------------------------------
// Carga guiada de gastos / ingresos.
// --------------------------------------------------------------
const expenseCategories={
  'comida':'Comida','casa':'Casa','salud':'Salud','educacion':'Educación','ocio':'Ocio',
  'impuestos':'Impuestos','gastos financieros':'Gastos financieros','gastos varios':'Gastos varios',
  'cositas de casa':'Cositas de Casa','vehiculos':'Vehículos'
};
const incomeTypes={
  '💼 sueldo':{label:'Sueldo',router:'sueldo'},'sueldo':{label:'Sueldo',router:'sueldo'},
  '🏪 cositas de casa':{label:'Cositas de Casa',router:'Cositas de Casa'},'cositas de casa':{label:'Cositas de Casa',router:'Cositas de Casa'},
  '🏛️ subsidios':{label:'Subsidios',router:'Subsidios'},'subsidios':{label:'Subsidios',router:'Subsidios'},
  '➕ otros ingresos':{label:'Otros ingresos',router:'Otros ingresos'},'otros ingresos':{label:'Otros ingresos',router:'Otros ingresos'}
};

if(st?.flow==='expense'){
  if(st.step==='category'){
    const category=expenseCategories[t]||null;
    if(!category) return [{json:{...trig,ui_mode:'expense_category',ui_only:true,ui_error:'Elegí una categoría.',chat_id:msg.chat?.id,ui_pending_write:false}}];
    const next={...st,category,step:'amount'};
    return [{json:{...trig,ui_mode:'expense_amount',ui_only:true,chat_id:msg.chat?.id,ui_pending_write:true,ui_pending_row:pendingRow(next,'importe','¿Cuánto gastaste?','PENDIENTE','UI_MOVIMIENTO')}}];
  }
  if(st.step==='amount'){
    const parsed=parseAmountDetail(raw);
    if(!parsed || parsed.amount<=0) return [{json:{...trig,ui_mode:'expense_amount',ui_only:true,ui_error:'Importe inválido. Ej.: 12500, 12500 supermercado, 2000 USD o 2000 USD cot 1510.',chat_id:msg.chat?.id,ui_pending_write:false}}];
    const next={...st,amount:parsed.amount,detail:parsed.detail,currency:parsed.currency||'ARS',cot:parsed.cot||null,date:todayIso(),step:'confirm'};
    return [{json:{...trig,ui_mode:'expense_confirm',ui_only:true,chat_id:msg.chat?.id,move_data:next,ui_pending_write:true,ui_pending_row:pendingRow(next,'confirmacion','¿Confirmar gasto?','PENDIENTE','UI_MOVIMIENTO')}}];
  }
  if(st.step==='confirm'){
    if(!['confirmar','✅ confirmar'].includes(t)) return [{json:{...trig,ui_mode:'expense_confirm',ui_only:true,ui_error:'Tocá Confirmar o Cancelar.',chat_id:msg.chat?.id,move_data:st,ui_pending_write:false}}];
    const payload=JSON.parse(JSON.stringify(trig));
    payload.message=payload.message||{};
    payload.message.text=String(st.currency||'ARS').toUpperCase()==='USD' ? `${st.category} ${st.amount} USD${st.cot?` cot ${st.cot}`:''}${st.detail?' '+st.detail:''}` : `${st.category} ${st.amount}${st.detail?' '+st.detail:''}`;
    return [{json:{
      ...trig,ui_mode:'forward_router',ui_only:true,chat_id:msg.chat?.id,
      router_payload:payload,forward_after_persist:true,ui_restore_main:true,
      ui_pending_write:true,ui_pending_row:pendingRow(st,'completo','Gasto confirmado','CONFIRMADO','UI_MOVIMIENTO')
    }}];
  }
}

if(st?.flow==='income'){
  if(st.step==='category'){
    const sel=incomeTypes[t]||null;
    if(!sel) return [{json:{...trig,ui_mode:'income_category',ui_only:true,ui_error:'Elegí el tipo de ingreso.',chat_id:msg.chat?.id,ui_pending_write:false}}];
    const next={...st,income_label:sel.label,income_router:sel.router,step:'amount'};
    return [{json:{...trig,ui_mode:'income_amount',ui_only:true,chat_id:msg.chat?.id,ui_pending_write:true,ui_pending_row:pendingRow(next,'importe','¿Cuánto ingresó?','PENDIENTE','UI_MOVIMIENTO')}}];
  }
  if(st.step==='amount'){
    const parsed=parseAmountDetail(raw);
    if(!parsed || parsed.amount<=0) return [{json:{...trig,ui_mode:'income_amount',ui_only:true,ui_error:'Importe inválido. Ej.: 500000 o 500000 sueldo octubre.',chat_id:msg.chat?.id,ui_pending_write:false}}];
    const next={...st,amount:parsed.amount,detail:parsed.detail,date:todayIso(),step:'confirm'};
    return [{json:{...trig,ui_mode:'income_confirm',ui_only:true,chat_id:msg.chat?.id,move_data:next,ui_pending_write:true,ui_pending_row:pendingRow(next,'confirmacion','¿Confirmar ingreso?','PENDIENTE','UI_MOVIMIENTO')}}];
  }
  if(st.step==='confirm'){
    if(!['confirmar','✅ confirmar'].includes(t)) return [{json:{...trig,ui_mode:'income_confirm',ui_only:true,ui_error:'Tocá Confirmar o Cancelar.',chat_id:msg.chat?.id,move_data:st,ui_pending_write:false}}];
    const payload=JSON.parse(JSON.stringify(trig));
    payload.message=payload.message||{};
    payload.message.text=`ingreso ${st.income_router} ${st.amount}${st.detail?' '+st.detail:''}`;
    return [{json:{
      ...trig,ui_mode:'forward_router',ui_only:true,chat_id:msg.chat?.id,
      router_payload:payload,forward_after_persist:true,ui_restore_main:true,
      ui_pending_write:true,ui_pending_row:pendingRow(st,'completo','Ingreso confirmado','CONFIRMADO','UI_MOVIMIENTO')
    }}];
  }
}

// Menú principal y acciones.
const exact={
  '/start':'main','/menu':'main','menu':'main','🏠 menu principal':'main','🏠 menú principal':'main',
  '💸 registrar gasto':'start_expense',
  '💰 registrar ingreso':'start_income',
  '📊 consultas':'menu_moves','🔎 movimientos':'menu_moves',
  '✏️ corregir movimiento':'correction_help',
  '📅 cierre mensual':'menu_close',
  '🛠️ corregir / pendientes':'menu_fix',
  '⚙️ mas':'menu_more','⚙️ más':'menu_more',
  '⚠️ ver pendientes':'show_pending',
  '🔧 diagnosticar problema':'diagnose',
  '📄 que documento falta':'missing_doc','📄 qué documento falta':'missing_doc',
  '🩺 estado del sistema':'system_status',
  'ℹ️ ayuda':'help'
};
let mode=exact[t]||null;

// Protección transitoria: si quedó visible un botón viejo del teclado anterior,
// vuelve al menú sin derivarlo al Router.
const retiredLegacyButtons=[
  '⏰ vencimientos','➕ cargar vencimiento','➕ cargar vencimientos',
  '➕ cargar faltante','⚠️ vencidos','⚠️ ver vencidos',
  '📆 proximos vencimientos','📆 próximos vencimientos'
];
if(retiredLegacyButtons.includes(t)) mode='main';

if(mode==='start_expense'){
  const start={flow:'expense',step:'category',started_at:new Date().toISOString()};
  return [{json:{...trig,ui_mode:'expense_category',ui_only:true,chat_id:msg.chat?.id,ui_pending_write:true,ui_pending_row:pendingRow(start,'categoria','Elegí la categoría del gasto.','PENDIENTE','UI_MOVIMIENTO')}}];
}
if(mode==='start_income'){
  const start={flow:'income',step:'category',started_at:new Date().toISOString()};
  return [{json:{...trig,ui_mode:'income_category',ui_only:true,chat_id:msg.chat?.id,ui_pending_write:true,ui_pending_row:pendingRow(start,'tipo_ingreso','Elegí el tipo de ingreso.','PENDIENTE','UI_MOVIMIENTO')}}];
}

const forwardMap={
  '📅 iniciar cierre mensual':'iniciar cierre mensual',
  '▶️ continuar cierre':'continuar cierre',
  '📋 ver progreso':'estado cierre',
  '❌ cancelar cierre':'cancelar cierre',
  '📋 gastos de este mes':'mostrame los gastos de este mes',
  '💵 ingresos de este mes':'mostrame los ingresos de este mes',
  '🏷️ gastos por categoria':'gastos por categoria este mes','🏷️ gastos por categoría':'gastos por categoria este mes',
  '💵 disponible':'cuanto disponible tenemos',
  '💳 deuda tarjetas':'cuanto debemos de tarjetas',
  '📈 inversiones':'inversiones',
  '🧾 patrimonio':'patrimonio'
};

if(!mode && forwardMap[t]){
  const out=JSON.parse(JSON.stringify(trig));
  out.message=out.message||{};
  out.message.text=forwardMap[t];
  return [{json:{...out,ui_only:false,ui_mode:'pass',ui_pending_write:false,ui_restore_main:false}}];
}

if(mode){
  return [{json:{...trig,ui_mode:mode,ui_only:true,chat_id:msg.chat?.id,ui_pending_write:false}}];
}

return [{json:{...trig,ui_only:false,ui_mode:'pass',ui_pending_write:false,ui_restore_main:false}}];

const base=$('UI - Detectar menú / flujo').first().json;
const mode=base.ui_mode;
const chatId=String(base.chat_id ?? base.message?.chat?.id ?? '');

const pend=$('UI - Leer Pendientes').all().map(i=>i.json).filter(r=>{
  const intent=String(r['Intención']||'').toUpperCase();
  return String(r['Chat ID']??'')===chatId &&
    String(r.Estado||'').toUpperCase()==='PENDIENTE' &&
    (intent==='UI_MOVIMIENTO' || !intent.startsWith('UI_'));
});
const checks=$('UI - Leer Cierre_Checklist').all().map(i=>i.json);

const activeClose=pend.find(r=>String(r['Intención']||'').toUpperCase()==='CIERRE_MENSUAL') || null;

function periodKey(r){return String(r.Periodo??'');}
const periods=[...new Set(checks.map(periodKey).filter(Boolean))].sort();
const currentPeriod=periods.length?periods[periods.length-1]:null;
const currentChecks=currentPeriod?checks.filter(r=>periodKey(r)===currentPeriod):[];

function num(v){
  if(v===null||v===undefined||v==='') return null;
  if(typeof v==='number') return v;
  let s=String(v).replace(/[^\d,.-]/g,'');
  if(s.includes(',')&&s.includes('.')) s=s.replace(/\./g,'').replace(',','.');
  else if(s.includes(',')) s=s.replace(',','.');
  const n=Number(s); return Number.isFinite(n)?n:null;
}
const missingDocs=currentChecks.filter(r=>{
  const st=String(r['Estado']??r['Estado conciliación']??'').toUpperCase();
  const tipo=String(r['Tipo control']??r.Tipo??'').toUpperCase();
  return (st===''||st==='PENDIENTE'||st==='FALTA') && /DOCUMENTO|TARJETA/.test(tipo);
});
const diffs=currentChecks.filter(r=>{
  const d=num(r['Diferencia ARS']??r['Diferencia cierre ARS']??r['Diferencia']??null);
  return d!==null && Math.abs(d)>0.01;
});
let screen=mode, message='';
if(base.ui_error) message='⚠️ '+base.ui_error+'\n\n';

if(mode==='main'){
  message+='🏠 Finanzas familiares\nElegí una opción. También podés escribir directamente como hasta ahora.';
}
else if(mode==='expense_category'){
  screen='expense_category'; message+='💸 Registrar gasto\nElegí la categoría:';
}
else if(mode==='expense_amount'){
  screen='expense_amount'; message+=`💸 ${base.ui_error?'':'Categoría: '+(base.ui_pending_row?JSON.parse(base.ui_pending_row['Datos parciales JSON']||'{}').category||'':'')+'\n'}Escribí el importe. Ej.: 12500 supermercado. Si es en dólares: 2000 USD o 2000 USD cot 1510.`;
}
else if(mode==='expense_confirm'){
  screen='expense_confirm';
  const x=base.move_data||(()=>{try{return JSON.parse(base.ui_pending_row?.['Datos parciales JSON']||'{}')}catch(e){return {}}})();
  const cur=String(x.currency||'ARS').toUpperCase();
  if(cur==='USD'){
    const cot=Number(x.cot||0);
    const eq=cot>0?Number(x.amount||0)*cot:null;
    message+=`💸 Confirmar gasto\n\n${x.category||'-'} — US$${Number(x.amount||0).toLocaleString('es-AR',{minimumFractionDigits:0,maximumFractionDigits:2})}\nEfectivo USD — ${x.date||''}${cot>0?`\nCotización real: $${cot.toLocaleString('es-AR',{maximumFractionDigits:2})}/USD\nEquivalente: $${eq.toLocaleString('es-AR',{minimumFractionDigits:0,maximumFractionDigits:2})}`:'\nSin cotización manual: se valuará para informes con la regla multimoneda.'}${x.detail?`\nDetalle: ${x.detail}`:''}\n\n¿Confirmar?`;
  }else{
    message+=`💸 Confirmar gasto\n\n${x.category||'-'} — $${Number(x.amount||0).toLocaleString('es-AR')}\nEfectivo — ${x.date||''}${x.detail?`\nDetalle: ${x.detail}`:''}\n\n¿Confirmar?`;
  }
}
else if(mode==='income_category'){
  screen='income_category'; message+='💰 Registrar ingreso\nElegí el tipo:';
}
else if(mode==='income_amount'){
  screen='income_amount'; message+='💰 Escribí el importe. Podés agregar un detalle opcional.';
}
else if(mode==='income_confirm'){
  screen='income_confirm';
  const x=base.move_data||(()=>{try{return JSON.parse(base.ui_pending_row?.['Datos parciales JSON']||'{}')}catch(e){return {}}})();
  message+=`💰 Confirmar ingreso\n\n${x.income_label||'-'} — $${Number(x.amount||0).toLocaleString('es-AR')}\nEfectivo — ${x.date||''}${x.detail?`\nDetalle: ${x.detail}`:''}\n\n¿Confirmar?`;
}
else if(mode==='correction_help'){
  screen='plain_main';
  message+='✏️ Corregir movimiento\n\nEscribilo así:\ncorregir Vehículos 13000 12/10 - monto 15000\n\nTambién podés cambiar categoría, fecha o detalle. Ej.:\ncorregir farmacia 50000 12/10 - categoria Salud\n\nTambién acepta la palabra “por” en lugar del guion.';
}
else if(mode==='forward_router'){
  screen='forward_router'; message='';
}
else if(mode==='menu_close'){
  screen=activeClose?'close_active':'close_idle';
  message+=activeClose?'📅 Hay un cierre mensual en curso.':'📅 No hay un cierre mensual pendiente.';
  if(currentPeriod) message+=`\nÚltimo período detectado: ${currentPeriod}.`;
}
else if(mode==='menu_moves'){
  screen='moves_menu';
  message+='📊 Consultas\nElegí una opción:';
}
else if(mode==='menu_fix'){
  const hasUseful=pend.length>0 || diffs.length>0 || missingDocs.length>0 || !!activeClose;
  screen=hasUseful?'fix_some':'fix_none';
  message+='🛠️ Corregir / Pendientes';
  if(pend.length) message+=`\nPendientes activos: ${pend.length}.`;
  else message+='\nNo hay pendientes activos.';
}
else if(mode==='menu_more'){
  screen='more_menu';
  message+='⚙️ Más';
}
else if(mode==='show_pending'){
  screen='plain_main';
  if(!pend.length) message+='✅ No hay pendientes activos.';
  else{
    message+=`⚠️ Pendientes activos: ${pend.length}\n\n`;
    message+=pend.slice(0,10).map((r,i)=>{
      const intent=String(r['Intención']||'Pendiente').replace(/_/g,' ');
      const q=String(r['Pregunta enviada']||r['Campo pendiente']||'').trim();
      return `${i+1}. ${intent}${q?` — ${q}`:''}`;
    }).join('\n');
    if(pend.length>10) message+=`\n… y ${pend.length-10} más.`;
  }
}
else if(mode==='missing_doc'){
  screen='plain_main';
  if(!currentPeriod) message+='No encuentro un cierre mensual iniciado.';
  else if(!missingDocs.length) message+=`✅ En ${currentPeriod} no falta ningún documento del checklist.`;
  else{
    message+=`📄 Documentos faltantes para ${currentPeriod}:\n`;
    message+=missingDocs.map(r=>`• ${r.Cuenta??r['Cuenta / tarjeta']??r['Item']??'Documento'}`).join('\n');
  }
}
else if(mode==='diagnose'){
  screen='plain_main';
  message+='🔧 Diagnóstico\n';
  if(!currentPeriod) message+='No hay checklist de cierre disponible.';
  else{
    message+=`Período: ${currentPeriod}\n`;
    if(!diffs.length && !missingDocs.length) message+='✅ No detecto diferencias de conciliación ni documentos faltantes.';
    if(diffs.length){
      message+=`\n⚠️ Diferencias:\n`+diffs.map(r=>{
        const d=num(r['Diferencia ARS']??r['Diferencia cierre ARS']??r.Diferencia);
        return `• ${r.Cuenta??r['Cuenta / tarjeta']??'Cuenta'}: $${Math.abs(d).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
      }).join('\n');
    }
    if(missingDocs.length){
      message+=`\n📄 Faltan:\n`+missingDocs.map(r=>`• ${r.Cuenta??r['Cuenta / tarjeta']??'Documento'}`).join('\n');
    }
  }
}
else if(mode==='system_status'){
  screen='plain_main';
  message+=`🩺 Estado del sistema\n`;
  message+=`• Cierre activo: ${activeClose?'Sí':'No'}\n`;
  message+=`• Pendientes: ${pend.length}\n`;
  message+=`• Documentos faltantes: ${missingDocs.length}\n`;
  message+=`• Diferencias detectadas: ${diffs.length}`;
}
else if(mode==='help'){
  screen='plain_main';
  message+='ℹ️ Usá el menú para cierres, consultas de movimientos y resolución de pendientes. También podés seguir escribiendo mensajes normales como hasta ahora.';
}
else{
  screen='main'; message+='🏠 Finanzas familiares\nElegí una opción:';
}
return [{json:{
  ...base,
  screen,
  message,
  ui_pending_write:!!base.ui_pending_write,
  ui_pending_row:base.ui_pending_row||null
}}];
